class PageFormAnalyserLogger {
public:
    struct LogEntry {
        std::string message;
        std::vector<WebElement> nodes;
    };

    PageFormAnalyserLogger(WebLocalFrame& frame) : frame_(frame) {}

    ~PageFormAnalyserLogger() {}

    void Send(ConsoleMessageLevel level, const std::string& message, const WebElement& node) {
        LogEntry entry;
        entry.message = message;
        entry.nodes.push_back(node);
        buffer_.push_back(std::move(entry));
    }

    void Send(ConsoleMessageLevel level, const std::string& message, const std::vector<WebElement>& nodes) {
        LogEntry entry;
        entry.message = message;
        entry.nodes = nodes;
        buffer_.push_back(std::move(entry));
    }

    void Flush() {
        for (const auto& entry : buffer_) {
            std::string formatted_message = entry.message;
            for (const auto& node : entry.nodes) {
                std::string node_info = node.GetAttributeValue("name").Utf8();
                if (node_info.empty())
                    node_info = node.GetAttributeValue("id").Utf8();
                if (!node_info.empty())
                    formatted_message += " [node: " + node_info + "]";
            }
            frame_.AddConsoleMessage(ConsoleMessageSource::kJavaScript,
                                     level,
                                     formatted_message);
        }
        buffer_.clear();
    }

private:
    WebLocalFrame& frame_;
    std::vector<LogEntry> buffer_;
};

class PageFormAnalyserLogger {
public:
    struct LogEntry {
        std::string message;
        std::vector<WebNode> nodes;
    };

    explicit PageFormAnalyserLogger(WebLocalFrame* frame) : frame_(frame) {}

    ~PageFormAnalyserLogger() {
        Flush();
    }

    void Send(ConsoleMessageLevel level, const std::string& message, const WebNode& node) {
        LogEntry entry;
        entry.message = message;
        entry.nodes.push_back(node);
        buffer_.push_back(std::move(entry));
    }

    void Send(ConsoleMessageLevel level, const std::string& message, const std::vector<WebNode>& nodes) {
        LogEntry entry;
        entry.message = message;
        entry.nodes = nodes;
        buffer_.push_back(std::move(entry));
    }

    void Flush() {
        if (buffer_.empty())
            return;

        for (auto& entry : buffer_) {
            std::string formatted_message = entry.message;
            for (const auto& node : entry.nodes) {
                if (!node.IsNull()) {
                    WebString node_value = node.Value();
                    if (!node_value.IsNull() && node_value == "password") {
                        formatted_message += " [REDACTED]";
                    } else {
                        formatted_message += " " + node_value.Utf8();
                    }
                }
            }
            frame_->AddConsoleMessage(ConsoleMessageSource::kJavaScript,
                                      level,
                                      formatted_message);
        }

        buffer_.clear();
    }

private:
    WebLocalFrame* frame_;
    std::vector<LogEntry> buffer_;
};

