typedef struct {
    char* message;
    WebNode* nodes;
    size_t node_count;
} LogEntry;

typedef struct {
    WebLocalFrame* frame;
    LogEntry* buffer;
    size_t buffer_size;
} PageFormAnalyserLogger;

void PageFormAnalyserLogger_Init(PageFormAnalyserLogger* logger, WebLocalFrame* frame) {
    logger->frame = frame;
    logger->buffer = NULL;
    logger->buffer_size = 0;
}

void PageFormAnalyserLogger_Destroy(PageFormAnalyserLogger* logger) {
    if (logger->buffer) {
        free(logger->buffer);
    }
    // Clean up any other resources if necessary.
}

void PageFormAnalyserLogger_Send(PageFormAnalyserLogger* logger, ConsoleLevel level, const char* message, WebNode* node) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->message = strdup(message);
    entry->nodes = (WebNode*)malloc(sizeof(WebNode));
    memcpy(entry->nodes, node, sizeof(WebNode));
    entry->node_count = 1;

    logger->buffer = realloc(logger->buffer, (logger->buffer_size + 1) * sizeof(LogEntry));
    logger->buffer[logger->buffer_size++] = *entry;
}

void PageFormAnalyserLogger_SendMultiple(PageFormAnalyserLogger* logger, ConsoleLevel level, const char* message, WebNode** nodes, size_t node_count) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->message = strdup(message);
    entry->nodes = (WebNode*)malloc(node_count * sizeof(WebNode));
    memcpy(entry->nodes, nodes, node_count * sizeof(WebNode));
    entry->node_count = node_count;

    logger->buffer = realloc(logger->buffer, (logger->buffer_size + 1) * sizeof(LogEntry));
    logger->buffer[logger->buffer_size++] = *entry;
}

void PageFormAnalyserLogger_Flush(PageFormAnalyserLogger* logger) {
    for (size_t i = 0; i < logger->buffer_size; ++i) {
        LogEntry entry = logger->buffer[i];
        char* filtered_message = strdup(entry.message);

